# Rule:        CKV2_AWS_18 (checkov 3.3.16)
# Applies to:  aws_backup_selection
# Read with:   a MEMBERSHIP join — two independent enumerations matched by key
#                left  aws_efs_file_system  keyed on arn (verbatim)
#                right aws_backup_protected_resource keyed on id (verbatim)
#
# The rule id is the identity: file name, control id and `tag checkov_id` all
# carry it, and tools/lint_catalog_drift.py asserts the three agree.

scan_regions = input('scan_regions')
exempt       = (input('exempt_assets') || {})['CKV2_AWS_18'] || []

control 'CKV2_AWS_18' do
  title 'Ensure that Elastic File System (Amazon EFS) file systems are added in the backup plans of AWS Backup'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the EFS file systems that actually exist, by enumerating them and the
    AWS Backup protected resource population separately and matching the two
    by key.

    DIVERGENCE from Checkov: Checkov asserts that a backup_selection
    resource EXISTS in the plan and names the file system.
    ListProtectedResources reports what has actually been backed up, so a
    file system selected by a plan that has never run reports as absent here
    and passes there.

    How the join is keyed, because a join whose keys never match reports
    every asset as uncovered and looks exactly like a real total finding:
    the left side is keyed on aws_efs_file_system.arn (verbatim), the right
    side on aws_backup_protected_resource.id (verbatim), and both keys carry
    the region they were read from, so a resource in one region cannot be
    covered by an entry in another.

    An empty right side is a FINDING, not an absence of evidence: AWS Backup
    holds no recovery point for any EFS file system in this account and
    region. That is the worst case for this rule, not an absence of
    evidence, so it renders as every file system failing rather than as Not
    Applicable.

    A region that could not be read on either side is asserted as its own
    failing example rather than being flattened into "found nothing" — an
    unread right side would otherwise report every asset here as uncovered.
  DESC

  desc 'rationale', <<~RATIONALE
    An EFS file system is usually shared mutable state for several workloads
    at once, so a bad write reaches all of them and there is no single owner
    who would notice. Without a recovery point there is nothing to roll back
    to.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: Ensure that Elastic File System (Amazon EFS) file
    systems are added in the backup plans of AWS Backup
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_backup_selection:

      resource "aws_backup_selection" "efs" {
        iam_role_arn = aws_iam_role.backup.arn
        name         = "efs-file-systems"
        plan_id      = aws_backup_plan.daily.id
        resources    = [aws_efs_file_system.shared.arn]
      }

    Out of band — aws_backup_selection:

      aws backup start-backup-job --backup-vault-name <vault> --resource-arn <file-system-arn> --iam-role-arn <role-arn>

    Note (aws_backup_selection): EFS also has its own automatic backups, which
    write to an AWS-managed vault. Those do NOT appear as an AWS Backup
    protected resource in every case, so a file system relying on them alone can
    fail this control; confirm which mechanism is in use before treating a
    failure as a gap.
  FIX

  tag checkov_id:            'CKV2_AWS_18'
  tag checkov_category:      'BACKUP_AND_RECOVERY'
  tag checkov_version:       '3.3.16'
  tag checkov_kind:          'graph'
  tag tf_resources:          %w[aws_backup_selection]
  tag tf_docs:               'https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/backup_selection'
  tag nist:                  ['CP-9', 'CP-10']
  tag nist_r4:               ['CP-9', 'CP-10']
  tag cci:                   ['CCI-000535', 'CCI-001678']
  tag ksi:                   ['KSI-RPL-RCY']
  tag severity:              'medium'
  tag severity_source:       'assessed'
  tag nist_source:           'agent-drafted'
  tag implementation_status: 'implemented'

  # Two independent enumerations, both resolved at CONTROL scope. What makes
  # this a join rather than the per-id lookup the stock shape already does is
  # that the right side cannot be fetched BY a left asset's id: it has to be
  # enumerated wholesale and matched.
  left_side  = aws_api_assets(type: 'aws_efs_file_system', regions: scan_regions)
  right_side = aws_api_assets(type: 'aws_backup_protected_resource', regions: scan_regions)

  # A region that could not be READ is not a region with nothing in it, and here
  # that cuts both ways. An unread RIGHT side makes every left asset look
  # uncovered — a 100% finding manufactured out of an API error — so both sides
  # are asserted, and `applicable` below keeps this visible even when the left
  # side came back empty because it was the side that failed.
  unreadable = left_side.unreadable_regions.map { |r| "aws_efs_file_system #{r[:region]}: #{r[:error]}" } +
               right_side.unreadable_regions.map { |r| "aws_backup_protected_resource #{r[:region]}: #{r[:error]}" }

  unless unreadable.empty?
    describe 'CKV2_AWS_18 join enumeration' do
      it 'read every region it attempted, on both sides of the join' do
        expect(unreadable).to be_empty
      end
    end
  end

  left_rows = left_side.assets(exempt: exempt)
  right_all = right_side.assets

  # The right side answers for every resource type in the account at once, so
  # it is narrowed BEFORE any key is built: a coverage question about EFS file systems
  # must not be satisfied by some other resource type that happens to reduce to
  # the same key.
  right_rows = checkov_membership_where(right_all, { resource_type: ['EFS'] })
  observed   = checkov_membership_observed(right_all, :resource_type)

  # Keys are built through one shared reducer for both sides, so the two cannot
  # drift into disagreeing about what a key is. A row that cannot be keyed is
  # COUNTED, not dropped: dropping it would remove exactly the population that
  # would have failed and render the control Not Applicable.
  keyed     = left_rows.map do |row|
    [row, checkov_membership_key(row, field: :arn, key_form: 'verbatim', match_region: true)]
  end
  unkeyable = keyed.count { |_row, key| key.nil? }
  in_scope  = keyed.reject { |_row, key| key.nil? }

  right_keys   = checkov_membership_keys(right_rows, field: :id,
                                         key_form: 'verbatim', match_region: true)
  matched      = in_scope.map { |row, key| [row, right_keys.key?(key)] }
  covered      = matched.count { |_row, hit| hit }
  left_sample  = checkov_membership_sample(in_scope.map { |_row, key| key })
  right_sample = checkov_membership_sample(right_keys.keys)

  if unkeyable.positive?
    describe 'aws_efs_file_system enumeration' do
      it 'produced a usable key for every row' do
        expect(unkeyable).to eq(0),
          "#{unkeyable} of #{left_rows.length} row(s) had no usable `arn` — the key "\
          'named in resource_map.yml is likely a field this spec does not carry, and every '\
          'such row is unjudgeable rather than compliant'
      end
    end
  end

  # `resource_type` is a service string, and the SDK declares it as a plain string
  # rather than an enum, so a mis-spelled filter value cannot be caught
  # statically. A wrong one empties the right side, which then reads as "nothing
  # is covered" — the same result as the genuine finding. This example does not
  # decide which of the two it is; it prints what the API actually returned so a
  # reader can, and it fails either way, because both readings are failures.
  if right_rows.empty? && !right_all.empty?
    describe 'aws_backup_protected_resource filter' do
      it 'selected at least one row of the declared resource_type' do
        expect(right_rows.length).to be > 0,
          "the mapping filters aws_backup_protected_resource to resource_type ['EFS'], and none of "\
          "the #{right_all.length} row(s) returned matched. The API returned "\
          "resource_type: #{observed.inspect}. If that list plainly contains the same "\
          'value in a different spelling, the mapping is wrong; if it does not, '\
          'nothing of this type is covered, which is the finding.'
      end
    end
  end

  # The join is only as good as the two key spaces lining up. Zero matches has
  # two readings and they are NOT equally likely: a broken join reports every
  # asset as uncovered, which is indistinguishable in the results from a real
  # total finding. So it is called out as its own failing example, with a sample
  # of each side's keys, rather than left to be inferred from EFS file systems
  # all failing at once.
  if !in_scope.empty? && !right_rows.empty? && covered.zero?
    describe 'CKV2_AWS_18 join key spaces' do
      it 'matched at least one EFS file system to the AWS Backup protected resource population' do
        expect(covered).to be > 0,
          "none of the #{in_scope.length} EFS file systems matched any of the "\
          "#{right_keys.length} AWS Backup protected resource key(s). Either nothing here is covered, or the "\
          'two sides are keyed in different identifier spaces and this join is broken. '\
          "left keys look like #{left_sample.inspect}; right keys look like "\
          "#{right_sample.inspect}, as region/key. If those are not the same kind "\
          'of string, the join is broken.'\
          ' If they ARE the same kind of string, compare the region halves: '\
          'this join pairs on region, so an asset covered from a different region '\
          'reads as uncovered here.'
      end
    end
  end

  # Not Applicable only when there are genuinely no EFS file systems to cover.
  # An EMPTY RIGHT SIDE is deliberately NOT part of this test:
  # AWS Backup holds no recovery point for any EFS file system in this
  # account and region. That is the worst case for this rule, not an absence
  # of evidence, so it renders as every file system failing rather than as
  # Not Applicable.
  # `unkeyable` and `unreadable` are in here for the same reason as in the stock
  # shape — a guard that only_if suppresses is not a guard.
  applicable = !in_scope.empty? || unkeyable.positive? || !unreadable.empty?
  impact 0.5
  impact 0.0 unless applicable
  only_if('no EFS file systems in scope') { applicable }

  matched.each do |row, hit|
    describe "aws_efs_file_system #{row[:id]} (#{row[:account_id]}/#{row[:region]})" do
      it 'is covered by an AWS Backup protected resource' do
        expect(hit).to eq(true), 'AWS Backup holds no recovery point for this EFS file system'
      end
    end
  end
end
